# generated by Google Gemini from .github/workflows/windows-release.yml
# this modifies some repository files in place

$ErrorActionPreference = "Stop"

function Invoke-Checked {
    param([scriptblock]$Command)
    & $Command
    if ($LASTEXITCODE -ne 0) {
        throw "Command failed with exit code $LASTEXITCODE"
    }
}

# Run from the repository root
Set-Location $PSScriptRoot

Write-Host "*** Set up Python 3.14 virtual environment" -ForegroundColor Cyan
if (-not (Test-Path ".venv")) {
    Invoke-Checked { py -3.14 -m venv .venv }
}
& ".\.venv\Scripts\Activate.ps1"

Write-Host "*** Update full version to {ver}+{date}git{hash}.windows" -ForegroundColor Cyan
$pyScript = @'
import json, re, subprocess
from datetime import datetime, timezone
from pathlib import Path

path = Path("dupeguru/core/__init__.py")
text = path.read_text(encoding="utf-8")

match = re.search(r'^__version__\s*=\s*["\']([^"\']+)["\']', text, re.MULTILINE)
version = match.group(1)
build_date = datetime.now(timezone.utc).strftime("%Y%m%d")
short_sha = subprocess.check_output(["git", "rev-parse", "--short", "HEAD"], text=True).strip()
new_full_version = f"{version}+{build_date}git{short_sha}.windows"

updated_text = re.sub(
    r'^(__full_version__\s*=\s*)["\'][^"\']+["\']',
    rf'\g<1>"{new_full_version}"',
    text,
    flags=re.MULTILINE,
)
path.write_text(updated_text, encoding="utf-8")

print(json.dumps({"version": version, "full_version": new_full_version}))
'@

$versionInfo = ($pyScript | Invoke-Checked { python - }) | ConvertFrom-Json
$Version = $versionInfo.version
$FullVersion = $versionInfo.full_version
Write-Host "Version: $Version | Full Version: $FullVersion" -ForegroundColor Green

Write-Host "*** Install Python build dependencies" -ForegroundColor Cyan
Invoke-Checked { python -m pip install --upgrade pip }
Invoke-Checked { python -m pip install -r requirements.txt -r requirements-extra.txt setuptools PySide6-Essentials }

Write-Host "*** Ensure NSIS is installed and on PATH" -ForegroundColor Cyan
$nsisDir = "C:\Program Files (x86)\NSIS"
if (-not (Test-Path "$nsisDir\makensis.exe") -and -not (Get-Command makensis -ErrorAction SilentlyContinue)) {
    Invoke-Checked { choco install nsis --no-progress --verbose -y }
}
if ((Test-Path $nsisDir) -and ($env:PATH -notlike "*$nsisDir*")) {
    $env:PATH = "$nsisDir;$env:PATH"
}

Write-Host "*** Check feature formatting and lint" -ForegroundColor Cyan
Invoke-Checked { python -m black --check . }
Invoke-Checked { python -m flake8 }

Write-Host "*** Build application" -ForegroundColor Cyan
Invoke-Checked { python build.py --clean }

Write-Host "*** Remove build-only PySide6 so PyInstaller only bundles PyQt6" -ForegroundColor Cyan
Invoke-Checked { python -m pip uninstall -y PySide6-Essentials shiboken6 }

Write-Host "*** Run core and Qt regression tests" -ForegroundColor Cyan
New-Item -ItemType Directory -Force -Path "build" | Out-Null
Invoke-Checked { python -m pytest dupeguru --junitxml=build/test-results.xml }

Write-Host "*** Package to Windows .exe files" -ForegroundColor Cyan
Invoke-Checked { python package.py }

Write-Host "*** Inspect generated files" -ForegroundColor Cyan
$installerPath = "dist/dupeguru_win64_$Version.exe"
$appExePath = "dist/dupeguru-win64/dupeguru-win64.exe"

if (-not (Test-Path $installerPath)) { throw "Installer missing: $installerPath" }
if (-not (Test-Path $appExePath)) { throw "Application missing: $appExePath" }

(Get-Item $appExePath).VersionInfo | Format-List *

Write-Host "*** Smoke test one, test it does not crash within 5 seconds" -ForegroundColor Cyan
$process = Start-Process -FilePath $appExePath -PassThru
try {
    Start-Sleep -Seconds 5
    if ($process.HasExited) {
        throw "Packaged application exited prematurely with code: $($process.ExitCode)"
    }
    Write-Output "Packaged Qt application started and is running cleanly (PID: $($process.Id))"
} finally {
    if (-not $process.HasExited) {
        $process.CloseMainWindow() | Out-Null
        if (-not $process.WaitForExit(5000)) {
            Stop-Process -Id $process.Id -Force
        }
    }
    $logFile = "$env:APPDATA\Hardcoded Software\dupeGuru\debug.log"
    if (Test-Path $logFile) { Get-Content $logFile }
}

Write-Host "*** Smoke test two, test with --smoke-test arg it stops within 10 seconds" -ForegroundColor Cyan
$process = Start-Process -FilePath $appExePath -ArgumentList "--smoke-test" -PassThru
try {
    if (-not $process.WaitForExit(10000)) { throw "Packaged application startup timed out" }
    if ($process.ExitCode -ne 0) { throw "Packaged application failed: $($process.ExitCode)" }
    Write-Output "Packaged Qt application initialized and exited successfully"
} finally {
    if (-not $process.HasExited) { Stop-Process -Id $process.Id -Force }
    $logFile = "$env:APPDATA\Hardcoded Software\dupeGuru\debug.log"
    if (Test-Path $logFile) { Get-Content $logFile }
}

Write-Host "*** Prepare release assets" -ForegroundColor Cyan
if (Test-Path "release") { Remove-Item -Recurse -Force "release" }
New-Item -ItemType Directory -Path "release" | Out-Null

Copy-Item $installerPath "release/dupeguru-$FullVersion-windows-x64-setup.exe"
New-Item -ItemType File -Force -Path "dist/dupeguru-win64/settings.ini" | Out-Null

Write-Host "*** Use full version in names" -ForegroundColor Cyan
$versionedDir = "dist/dupeguru-$FullVersion"
if (Test-Path $versionedDir) { Remove-Item -Recurse -Force $versionedDir }
Rename-Item -Path "dist/dupeguru-win64" -NewName "dupeguru-$FullVersion"
Compress-Archive -Path $versionedDir -DestinationPath "release/dupeguru-$FullVersion-windows-x64-portable.zip"

Write-Host "*** Compute hashes for release items" -ForegroundColor Cyan
Get-ChildItem "release" -File | ForEach-Object {
    $hash = (Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLower()
    "$hash  $($_.Name)"
} | Set-Content "release/SHA256SUMS.txt"

Copy-Item "build/test-results.xml" "release/test-results.xml"

Write-Host "*** List release assets" -ForegroundColor Green
Get-ChildItem -Force -Recurse "release"
